import { createHash } from "node:crypto";
import type {
	CreateSandboxFromImageParams,
	CreateSandboxFromSnapshotParams,
	Daytona,
	Sandbox as DaytonaSandbox,
} from "@daytona/sdk";
import { type Sandbox, type SandboxFactory, useSandbox } from "@flue/runtime";

/** Client that creates and finds rouar VMs. */
export type VMClient = Daytona;
/** A rouar VM. */
export type VM = DaytonaSandbox;

/** Label that holds the Flue instance id. */
export const INSTANCE_LABEL = "rouar_instance";
/** Label that holds the rouar environment id, so production and previews use separate VMs. */
export const ENVIRONMENT_LABEL = "rouar_environment";
/** Label that holds the rouar project id, so a VM is never picked up by another project. */
export const PROJECT_LABEL = "rouar_project";

/** Settings for creating a VM from a snapshot or from an image. */
export type UseVMCreateParams =
	| CreateSandboxFromSnapshotParams
	| CreateSandboxFromImageParams;

export type UseVMOptions = {
	/**
	 * Settings used when the VM is created. They override defaults such as `autoStopInterval`.
	 * The `rouar_instance`, `rouar_environment`, and `rouar_project` labels cannot be overridden.
	 */
	create?: UseVMCreateParams;
	/** Working directory for the agent. */
	cwd?: string;
	/** Seconds to wait for the VM to start. Defaults to 120. */
	timeoutSeconds?: number;
	/**
	 * Client to use. When omitted, a client is created from `ROUAR_TOKEN` and `ROUAR_VM_URL`,
	 * which are set on rouar deployments.
	 */
	client?: VMClient;
};

/** Default lifetime: stop after 15 idle minutes, archive after 1 day, and delete 7 days after stopping. */
export const DEFAULT_CREATE_PARAMS = {
	autoStopInterval: 15,
	autoArchiveInterval: 60 * 24,
	autoDeleteInterval: 60 * 24 * 7,
} as const satisfies UseVMCreateParams;

const DEAD_STATES = new Set([
	"destroyed",
	"destroying",
	"error",
	"build_failed",
]);
const STOPPED_STATES = new Set(["stopped", "archived", "paused"]);
/** 接頭辞の id- を付けても 63 文字に収まる id */
const RAW_ID = /^[A-Za-z0-9._-]{1,60}$/;

/**
 * Turns an instance id into a label value: `id-<id>` when the id can be used as is,
 * or `sha256-<hex>` when it has unsupported characters or is too long.
 * The prefixes keep the two forms from colliding.
 */
export function instanceLabelValue(id: string): string {
	if (RAW_ID.test(id)) return `id-${id}`;
	return `sha256-${createHash("sha256").update(id, "utf8").digest("hex").slice(0, 56)}`;
}

let sharedClient: { key: string; client: Promise<VMClient> } | undefined;

async function defaultClient(): Promise<VMClient> {
	const apiKey = process.env.ROUAR_TOKEN;
	const apiUrl = process.env.ROUAR_VM_URL;
	if (!apiKey || !apiUrl) {
		throw new Error(
			"[rouar] useVM() needs ROUAR_TOKEN and ROUAR_VM_URL. They are set on rouar deployments; for local runs pass `client` to useVM().",
		);
	}
	const key = `${apiUrl}\n${apiKey}`;
	if (sharedClient?.key !== key) {
		sharedClient = {
			key,
			client: import("@daytona/sdk").then(
				({ Daytona }) =>
					new Daytona({
						apiKey,
						apiUrl,
						// rouar のゲートウェイは WebSocket を通さないので、状態はいつもポーリングで見る
						useDeprecatedPolling: true,
					}),
			),
		};
	}
	return sharedClient.client;
}

/** Finds the VM for the instance by its labels, creating it if needed and starting it if stopped. */
export async function findOrCreateSandbox(
	client: VMClient,
	instanceId: string,
	options: Pick<UseVMOptions, "create" | "timeoutSeconds"> = {},
	env: Record<string, string | undefined> = process.env,
): Promise<VM> {
	const labels: Record<string, string> = {
		[INSTANCE_LABEL]: instanceLabelValue(instanceId),
	};
	if (env.ROUAR_ENVIRONMENT_ID)
		labels[ENVIRONMENT_LABEL] = env.ROUAR_ENVIRONMENT_ID;
	if (env.ROUAR_PROJECT_ID) labels[PROJECT_LABEL] = env.ROUAR_PROJECT_ID;
	const timeout = options.timeoutSeconds ?? 120;

	for await (const sandbox of client.list({ labels })) {
		const state = sandbox.state ?? "";
		if (DEAD_STATES.has(state)) continue;
		if (STOPPED_STATES.has(state)) await sandbox.start(timeout);
		return sandbox;
	}
	const create = options.create ?? {};
	return client.create(
		{
			...DEFAULT_CREATE_PARAMS,
			...create,
			labels: { ...create.labels, ...labels },
		},
		{ timeout },
	);
}

/** 同じインスタンスで同時に作らないように、作っている途中の Promise を共有する */
const pending = new Map<string, Promise<VM>>();

/** The sandbox factory behind `useVM()`. Use it when you need a Flue `SandboxFactory` outside a hook. */
export function rouarVM(options: UseVMOptions = {}): SandboxFactory {
	return {
		async createSandbox({ id }): Promise<Sandbox> {
			const client = options.client ?? (await defaultClient());
			let sandboxPromise = pending.get(id);
			if (!sandboxPromise) {
				sandboxPromise = findOrCreateSandbox(client, id, options);
				pending.set(id, sandboxPromise);
				void sandboxPromise
					.finally(() => pending.delete(id))
					.catch(() => undefined);
			}
			const sandbox = await sandboxPromise;
			const { daytona } = await import("./vm-adapter");
			return daytona(sandbox).createSandbox({ id });
		},
	};
}

/**
 * Attaches a rouar VM to the agent. Call it in the agent body or in a hook called from it.
 * Each Flue instance gets one VM, and later runs of the same instance reuse it.
 * It cannot be combined with `useSandbox()` in the same agent.
 */
export function useVM(options: UseVMOptions = {}): void {
	useSandbox(rouarVM(options), options.cwd ? { cwd: options.cwd } : {});
}
